        "code": "# GearsBot Cage Bot, ev3dev2 Python. Press Reset before Run.\nfrom ev3dev2.motor import LargeMotor, OUTPUT_C, SpeedDPS\nfrom ev3dev2.sensor.lego import ColorSensor, UltrasonicSensor\nfrom time import time, sleep\n\ntry:\n    color = ColorSensor(\"in3\")\n    sonar = UltrasonicSensor(\"in4\")\n    arm = LargeMotor(OUTPUT_C)\nexcept Exception as error:\n    print(\"SETUP:\", error)\n    raise RuntimeError(\"Select Cage Bot, then press Reset.\")\n\ndef move_arm(target, deadline):\n    if not 0 <= target <= 45:\n        raise ValueError(\"Use an arm target from 0 to 45 degrees.\")\n    if time() >= deadline:\n        return False\n    limit = min(deadline, time() + 3.0)\n    arm.on_to_position(SpeedDPS(30), target, brake=True, block=False)\n    while abs(arm.position - target) > 2:\n        if time() >= limit:\n            arm.off(brake=True)\n            return False\n        sleep(0.02)\n    arm.off(brake=True)\n    return time() < limit\n\ndef read_group():\n    samples = []\n    for sample in range(3):\n        samples.append(color.color)\n        sleep(0.05)\n    if samples[0] == samples[1] == samples[2]:\n        if samples[0] == 5:  # EV3 red\n            return \"A\"\n        elif samples[0] == 2:  # EV3 blue\n            return \"B\"\n    return \"CHECK\"\n\ndef wait_zone(near, deadline):\n    stable = 0\n    while time() < deadline:\n        distance = sonar.distance_centimeters\n        if distance <= 0:\n            return False\n        matches = distance <= 3.0 if near else distance >= 8.0\n        stable = stable + 1 if matches else 0\n        if stable >= 3:\n            return True\n        sleep(0.05)\n    return False\n\n# Prepare objects in this exact order. CHECK uses a yellow object.\nexpected_groups = [\"A\", \"B\", \"CHECK\", \"A\", \"B\",\n                   \"A\", \"CHECK\", \"B\", \"A\", \"B\"]\nresults = []\nrecognized = passed = 0\nmotor_fault = False\nend_time = time() + 240.0\ntry:\n    if not move_arm(45, end_time):\n        raise RuntimeError(\"Arm opening timeout; inspect and Reset.\")\n    for index in range(len(expected_groups)):\n        expected = expected_groups[index]\n        observed, status = \"NO_READING\", \"WAIT_CLEAR_TIMEOUT\"\n        print(\"Trial\", index + 1, \"expected\", expected,\n              \"reverse until clear, then approach the next object\")\n        if wait_zone(False, min(end_time, time() + 10.0)):\n            print(\"APPROACH: 20 seconds\")\n            status = \"OBJECT_TIMEOUT\"\n            if wait_zone(True, min(end_time, time() + 20.0)):\n                observed = read_group()\n                status = \"CHECK\" if observed == \"CHECK\" else \"OBJECT_MOVED\"\n                if observed != \"CHECK\" and 0 < sonar.distance_centimeters <= 3.0:\n                    if move_arm(0, end_time) and move_arm(45, end_time):\n                        status = \"GATE_OK\"\n                    else:\n                        status = \"GATE_TIMEOUT\"\n                        motor_fault = True\n        recognition_ok = observed == expected\n        protocol_ok = recognition_ok and (\n            status == \"GATE_OK\" or (expected == \"CHECK\" and status == \"CHECK\"))\n        recognized += int(recognition_ok)\n        passed += int(protocol_ok)\n        results.append([index + 1, expected, observed, status])\n        print(\"RESULT\", results[-1], \"pass\", protocol_ok)\n        if motor_fault or time() >= end_time:\n            print(\"STOP: inspect the robot before another run.\")\n            break\nfinally:\n    arm.off(brake=True)\n\nattempted = len(results)  # Includes every timeout and incorrect result.\nprint(\"planned\", len(expected_groups), \"attempted\", attempted)\nif attempted:\n    print(\"recognition_percent\", round(100.0 * recognized / attempted, 1))\n    print(\"classification_and_gate_percent\", round(100.0 * passed / attempted, 1))\nprint(\"complete_test\", attempted == len(expected_groups))\nprint(\"These results measure labels and arm cycles; record destination bins separately.\")\n",
