        "code": "# GearsBot Cage Bot, ev3dev2 Python. Press Reset before Run.\nfrom ev3dev2.motor import LargeMotor, OUTPUT_C, SpeedDPS\nfrom ev3dev2.sensor.lego import ColorSensor, UltrasonicSensor\nfrom time import time, sleep\n\ntry:\n    color = ColorSensor(\"in3\")\n    sonar = UltrasonicSensor(\"in4\")\n    arm = LargeMotor(OUTPUT_C)\nexcept Exception as error:\n    print(\"SETUP:\", error)\n    raise RuntimeError(\"Select Cage Bot, then press Reset.\")\n\ndef move_arm(target, deadline):\n    if not 0 <= target <= 45:\n        raise ValueError(\"Use an arm target from 0 to 45 degrees.\")\n    if time() >= deadline:\n        return False\n    limit = min(deadline, time() + 3.0)\n    arm.on_to_position(SpeedDPS(30), target, brake=True, block=False)\n    while abs(arm.position - target) > 2:\n        if time() >= limit:\n            arm.off(brake=True)\n            return False\n        sleep(0.02)\n    arm.off(brake=True)\n    return time() < limit\n\ndef read_group():\n    samples = []\n    for sample in range(3):\n        samples.append(color.color)\n        sleep(0.05)\n    if samples[0] == samples[1] == samples[2]:\n        if samples[0] == 5:  # EV3 red\n            return \"A\"\n        elif samples[0] == 2:  # EV3 blue\n            return \"B\"\n    return \"CHECK\"\n\nstate = \"WAIT\"\nphase = \"\"\ntarget = 45\nphase_deadline = 0.0\nclear_samples = 0\nreceived = gate_cycles = needs_check = 0\nend_time = time() + 90.0\ntry:\n    if not move_arm(45, end_time):\n        raise RuntimeError(\"Arm opening timeout; inspect and Reset.\")\n    print(state)\n    while time() < end_time:\n        distance = sonar.distance_centimeters\n        if distance <= 0:\n            state = \"ERROR\"\n            print(state, \"invalid or contact-distance reading\")\n            break\n\n        if state == \"WAIT\" and distance <= 3.0:\n            received += 1\n            group = read_group()\n            if group == \"CHECK\":\n                needs_check += 1\n                state = \"WAIT_CLEAR\"\n                clear_samples = 0\n                print(state, \"CHECK\", received)\n            elif not (0 < sonar.distance_centimeters <= 3.0):\n                state = \"WAIT_CLEAR\"\n                clear_samples = 0\n                print(state, \"object moved\")\n            elif time() >= end_time:\n                state = \"ERROR\"\n                print(state, \"run deadline before gate cycle\")\n                break\n            else:\n                phase, target = \"CLOSE\", 0\n                phase_deadline = min(end_time, time() + 3.0)\n                arm.on_to_position(SpeedDPS(30), target, brake=True, block=False)\n                state = \"CLASSIFY\"\n                print(state, group, \"object\", received)\n\n        elif state == \"CLASSIFY\":\n            if time() >= phase_deadline:\n                state = \"ERROR\"\n                print(state, \"arm timeout\", phase)\n                break\n            elif abs(arm.position - target) <= 2:\n                arm.off(brake=True)\n                if phase == \"CLOSE\":\n                    phase, target = \"OPEN\", 45\n                    phase_deadline = min(end_time, time() + 3.0)\n                    arm.on_to_position(SpeedDPS(30), target, brake=True, block=False)\n                else:\n                    gate_cycles += 1\n                    state = \"WAIT_CLEAR\"\n                    clear_samples = 0\n                    print(state, \"gate_cycles\", gate_cycles)\n\n        elif state == \"WAIT_CLEAR\":\n            clear_samples = clear_samples + 1 if distance >= 8.0 else 0\n            if clear_samples >= 3:\n                state = \"WAIT\"\n                print(state)\n        sleep(0.05)\n    if state == \"CLASSIFY\":\n        state = \"ERROR\"\n        print(state, \"run deadline during unfinished gate cycle\")\nfinally:\n    arm.off(brake=True)\nprint(\"state\", state, \"received\", received,\n      \"gate_cycles\", gate_cycles, \"needs_check\", needs_check)\n",
