        "code": "from math import pi, sqrt\nfrom time import time, sleep\nfrom ev3dev2.motor import MoveTank, OUTPUT_A, OUTPUT_B\nfrom ev3dev2.sensor import INPUT_4\nfrom ev3dev2.sensor.virtual import GPSSensor\n\ntank = MoveTank(OUTPUT_A, OUTPUT_B)\ngps = GPSSensor(INPUT_4)\nWHEEL_DIAMETER_MM = 56.0\nTRACK_WIDTH_MM = 152.0\nSPEED = 25\n\ndef move_wheels(left_speed, right_speed, degrees, timeout_s=8.0):\n    start_left = tank.left_motor.position\n    start_right = tank.right_motor.position\n    deadline = time() + timeout_s\n    tank.on_for_degrees(left_speed, right_speed, degrees,\n                        brake=True, block=False)\n    try:\n        sleep(0.05)\n        while time() < deadline:\n            if tank.left_motor.is_stalled or tank.right_motor.is_stalled:\n                raise RuntimeError(\"Motor stalled; check the course\")\n            if not (tank.left_motor.is_running or tank.right_motor.is_running):\n                left_done = abs(tank.left_motor.position - start_left)\n                right_done = abs(tank.right_motor.position - start_right)\n                if min(left_done, right_done) >= degrees - 5:\n                    return\n            sleep(0.02)\n        raise RuntimeError(\"Motion timeout; reset before retrying\")\n    finally:\n        tank.off(brake=True)\n\ndef forward(distance_mm):\n    degrees = 360.0 * distance_mm / (pi * WHEEL_DIAMETER_MM)\n    move_wheels(SPEED, SPEED, degrees)\n\ndef turn_right(angle_deg=90):\n    degrees = angle_deg * TRACK_WIDTH_MM / WHEEL_DIAMETER_MM\n    move_wheels(SPEED, -SPEED, degrees)\n\ndef turn_left(angle_deg=90):\n    degrees = angle_deg * TRACK_WIDTH_MM / WHEEL_DIAMETER_MM\n    move_wheels(-SPEED, SPEED, degrees)\n\nstart = gps.position\ntry:\n    for side in range(4):\n        forward(200)\n        turn_right(90)\n        print(\"Completed side:\", side + 1, \"GPS (cm):\", gps.position[:2])\n    end = gps.position\n    error_mm = 10 * sqrt((end[0] - start[0]) ** 2\n                        + (end[1] - start[1]) ** 2)\n    print(\"Return-position error (mm):\", round(error_mm, 1))\n    print(\"Commands: 4 forward, 4 right turns\")\nfinally:\n    tank.off(brake=True)\n",
