        "code": "# Deterministic grid experiments. Times below are declared action costs.\nWIDTH, HEIGHT = 5, 4\nSTART, GOAL = (0, 0), (4, 3)\nMAPS = [set(), {(1, 0), (1, 1), (1, 2)},\n        {(2, 0), (2, 1), (2, 2), (2, 3)}]\nFORWARD_S, TURN_S = 1.0, 0.5\nEXPANSION_LIMIT = 100\nDIRECTIONS = [(1, 0), (0, 1), (-1, 0), (0, -1)]\n\ndef search(blocked, mode):\n    frontier = [START]\n    parent = {START: None}\n    expanded = 0\n    while frontier and expanded < EXPANSION_LIMIT:\n        current = frontier.pop(0) if mode == \"BFS\" else frontier.pop()\n        expanded += 1\n        if current == GOAL:\n            path = []\n            while current is not None:\n                path.append(current)\n                current = parent[current]\n            return path[::-1], expanded, \"goal_reached\"\n        x, y = current\n        for dx, dy in DIRECTIONS:\n            neighbor = (x + dx, y + dy)\n            nx, ny = neighbor\n            if (0 <= nx < WIDTH and 0 <= ny < HEIGHT\n                    and neighbor not in blocked and neighbor not in parent):\n                parent[neighbor] = current\n                frontier.append(neighbor)\n    reason = \"expansion_limit\" if frontier else \"no_path\"\n    return None, expanded, reason\n\ndef path_cost(path):\n    heading = 0  # east\n    turns = 0\n    for current, following in zip(path, path[1:]):\n        delta = (following[0] - current[0], following[1] - current[1])\n        next_heading = DIRECTIONS.index(delta)\n        change = (next_heading - heading) % 4\n        turns += min(change, 4 - change)\n        heading = next_heading\n    steps = len(path) - 1\n    return steps, turns, steps * FORWARD_S + turns * TURN_S\n\nfor mode in [\"BFS\", \"DFS\"]:\n    completed = 0\n    successful_costs = []\n    for map_id, blocked in enumerate(MAPS, 1):\n        path, expanded, reason = search(blocked, mode)\n        if path is None:\n            print(mode, \"map\", map_id, reason, \"expanded:\", expanded)\n        else:\n            steps, turns, cost_s = path_cost(path)\n            completed += 1\n            successful_costs.append(cost_s)\n            print(mode, \"map\", map_id, reason, \"steps:\", steps,\n                  \"turns:\", turns, \"model seconds:\", cost_s,\n                  \"expanded:\", expanded)\n    print(mode, \"completion:\", completed, \"/\", len(MAPS))\n    mean_cost = sum(successful_costs) / completed if completed else None\n    print(\"Mean model seconds on successful maps:\", mean_cost)\n",
